local bdTotal = 0
for (trial: 1 .. 100) {
  local seen = {}
  local draws = 0
  local dup = false
  while (!dup) {
    draws = draws + 1
    local b = randInt(1,365)
    if (seen.containsKey(b)) { dup = true } else { seen.set(b, true) }
  }
  bdTotal = bdTotal + draws
}
println(formatDecimal(bdTotal/100, 0))

