local betaSamples = []
local betaM = 2.074
while (betaSamples.listLen() < 1000) {
  local x = randFloat()
  local u = randFloat()
  local fx = 12 * x * (1-x)^2
  if (u <= fx / betaM) { betaSamples.add(x) }
}
println(formatDecimal(avgOf(betaSamples), 1))
